-- DROP TABLE IF EXISTS platform.error_code_registry CASCADE;
-- DROP TABLE IF EXISTS platform.system_config CASCADE;
-- DROP TABLE IF EXISTS platform.schema_migrations CASCADE;
-- DROP TABLE IF EXISTS platform.api_request_log CASCADE;
-- DROP TABLE IF EXISTS platform.rate_limit_counters CASCADE;
-- DROP TABLE IF EXISTS platform.feature_flag_audit CASCADE;
-- DROP TABLE IF EXISTS platform.feature_flags CASCADE;
-- DROP TABLE IF EXISTS platform.gdpr_erasure_requests CASCADE;
